// This file was generated by Prisma, and assumes you run Prisma commands using `bun --bun run prisma [command]`.
import dotenv from "dotenv";
import path from "path";
import { defineConfig } from "prisma/config";

const repoRoot = path.resolve(import.meta.dirname, "../..");

dotenv.config({ path: path.join(repoRoot, ".env") });

// Resolve a relative SQLite file: URL against the repo root so the Prisma CLI
// (migrations / db push) targets the same database file as the runtime client.
function resolveSqliteUrl(raw: string | undefined): string {
  const value = raw ?? "file:./cerberus.db";
  const match = /^file:(.*)$/.exec(value);
  if (!match) return value;
  const filePath = match[1]!;
  if (filePath.startsWith("/") || filePath.startsWith(":")) return value;
  return `file:${path.resolve(repoRoot, filePath)}`;
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: resolveSqliteUrl(process.env.DATABASE_URL),
  },
});
